mkitem!{mkstruct!{# [doc = " An IPv4 address."] # [doc = ""] # [doc = " IPv4 addresses are defined as 32-bit integers in [IETF RFC 791]."] # [doc = " They are usually represented as four octets."] # [doc = ""] # [doc = " See [`IpAddr`] for a type encompassing both IPv4 and IPv6 addresses."] # [doc = ""] # [doc = " [IETF RFC 791]: https://tools.ietf.org/html/rfc791"] # [doc = ""] # [doc = " # Textual representation"] # [doc = ""] # [doc = " `Ipv4Addr` provides a [`FromStr`] implementation. The four octets are in decimal"] # [doc = " notation, divided by `.` (this is called \"dot-decimal notation\")."] # [doc = " Notably, octal numbers (which are indicated with a leading `0`) and hexadecimal numbers (which"] # [doc = " are indicated with a leading `0x`) are not allowed per [IETF RFC 6943]."] # [doc = ""] # [doc = " [IETF RFC 6943]: https://tools.ietf.org/html/rfc6943#section-3.1.1"] # [doc = " [`FromStr`]: crate::str::FromStr"] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use std::net::Ipv4Addr;"] # [doc = ""] # [doc = " let localhost = Ipv4Addr::new(127, 0, 0, 1);"] # [doc = " assert_eq!(\"127.0.0.1\".parse(), Ok(localhost));"] # [doc = " assert_eq!(localhost.is_loopback(), true);"] # [doc = " assert!(\"012.004.002.000\".parse::<Ipv4Addr>().is_err()); // all octets are in octal"] # [doc = " assert!(\"0000000.0.0.0\".parse::<Ipv4Addr>().is_err()); // first octet is a zero in octal"] # [doc = " assert!(\"0xcb.0x0.0x71.0x00\".parse::<Ipv4Addr>().is_err()); // all octets are in hex"] # [doc = " ```"] # [rustc_diagnostic_item = "Ipv4Addr"] # [derive (Copy , Clone , PartialEq , Eq)] # [stable (feature = "rust1" , since = "1.0.0")] pub struct Ipv4Addr { octets : [u8 ; 4] , }}}
